design_text:
{
  "site_summary": "A partial shade courtyard with moderate moisture and no pets present, designed primarily for visual interest.",
  "layout_strategy": "The scheme stacks three distinct height layers: trailing and climbing elements at the vertical level along walls and trellises, structural upright shrubs and herbs at the mid-height container level, and soft textural herbs and foliage spreading at the ground level.",
  "combination_logic": "The plants combine fine feathery foliage with glossy thick leaves and delicate blooms, offering a contrast in height, soft textures, and aromatic scents that change across the seasons with summer flowering and lush green growth.",
  "zones": [
    {
      "zone_name": "Vertical Canopy",
      "zone_role": "screening",
      "layer": "vertical",
      "placement": "On the upper wall trellis, partial shade with dappled light throughout the day.",
      "plants": [
        {
          "scientific_name": "Jasminum species",
          "common_name": "Jasmine",
          "why": "Provides vertical height and fragrant climbing habit in partial shade.",
          "role_in_combination": "Contributes height and sweet fragrance, creating a dramatic backdrop for the mid-level plants."
        },
        {
          "scientific_name": "Hoya carnosa",
          "common_name": "Honey Plant",
          "why": "Suited for wall-mounted pots in partial shade with moderate moisture.",
          "role_in_combination": "Adds glossy, succulent foliage and waxy flowers that contrast texturally against the fine foliage of the jasmine."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top two inches of soil are dry.",
        "Feed with a balanced liquid fertilizer monthly during the growing season.",
        "Prune back unruly stems after the main flowering period."
      ]
    },
    {
      "zone_name": "Mid-Level Structure",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "In raised containers against the courtyard walls, receiving dappled light and partial shade.",
      "plants": [
        {
          "scientific_name": "Hibiscus syriacus",
          "common_name": "Hibiscus",
          "why": "Forms a lovely mid-height woody shrub structure thriving in partial shade.",
          "role_in_combination": "Acts as the structural focal point with large, showy blossoms that draw the eye."
        },
        {
          "scientific_name": "Aloysia triphylla",
          "common_name": "Lemon Verbena",
          "why": "Brings shrubby texture and a powerful citrus scent to mid-height pots.",
          "role_in_combination": "Contributes rough-textured lance-shaped leaves and releases a fresh aroma when brushed against."
        }
      ],
      "maintenance": [
        "Water consistently to keep the potting mix evenly moist.",
        "Fertilize every three weeks in spring and summer.",
        "Prune woody stems in early spring to encourage bushy new growth."
      ]
    },
    {
      "zone_name": "Ground Level Texture",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "Along the perimeter floor edges of the courtyard in partial shade with moderate moisture.",
      "plants": [
        {
          "scientific_name": "Foeniculum vulgare",
          "common_name": "Fennel",
          "why": "Offers fine, feathery foliage at ground level in partial shade conditions.",
          "role_in_combination": "Provides a striking contrast in texture with its needle-like green leaves against broader-leaved plants."
        },
        {
          "scientific_name": "Anethum graveolena",
          "common_name": "Dill",
          "why": "Thrives in moderate moisture and partial shade at the base of larger pots.",
          "role_in_combination": "Fills in gaps with delicate, airy umbels that soften the hard edges of the containers."
        }
      ],
      "maintenance": [
        "Water frequently to maintain steady soil moisture without waterlogging.",
        "Remove spent flower heads to prolong foliage life.",
        "Sow new seeds annually for continuous ground-level coverage."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture and water containers thoroughly",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer and Spring"
    },
    {
      "task": "Apply a balanced liquid fertilizer to support lush foliage and blooms",
      "frequency": "Monthly",
      "season": "Spring and Summer"
    },
    {
      "task": "Prune back dead or damaged stems and clear fallen debris",
      "frequency": "As needed, major prune once",
      "season": "Early Spring"
    }
  ],
  "care_cautions": [
    "Overwatering the Hoya carnosa and Hibiscus syriacus in the vertical and mid-level pots can lead to root rot due to insufficient drainage in heavy shade.",
    "The fine foliage of Foeniculum vulgare and Anethum graveolena may dry out quickly during unexpectedly hot spells in the partial shade courtyard."
  ],
  "pet_safety_note": "Since no pets live in the household, this scheme focuses entirely on visual and aromatic human enjoyment without pet-toxicity restrictions."
}
